using System; using System.Drawing; using System.Windows.Forms;
namespace ProyectoMatematicoWinForms {
 public class JuegoForm:Form {
  string[] nombres=new string[10]; int[] puntajes=new int[10]; int cantidad; readonly string[] jugadores=new string[2]; readonly JuegoLogica[] juegos=new JuegoLogica[2]; readonly bool dos; int turno;
  Label jugador,nivel,puntaje,vidas,pregunta; TextBox respuesta; Button responder,finalizar;
  public JuegoForm(string a,string b,bool d){jugadores[0]=a;jugadores[1]=b;dos=d;juegos[0]=new JuegoLogica();juegos[1]=new JuegoLogica();Text="Proyecto Matemático - Juego";StartPosition=FormStartPosition.CenterScreen;Size=new Size(650,500);Crear();Actualizar();}
  void Crear(){Controls.Add(new Label{Text="JUEGO MATEMÁTICO",Font=new Font("Segoe UI",20,FontStyle.Bold),AutoSize=true,Location=new Point(200,25)});jugador=new Label{AutoSize=true,Font=new Font("Segoe UI",13,FontStyle.Bold),Location=new Point(55,90)};nivel=new Label{AutoSize=true,Location=new Point(55,135)};puntaje=new Label{AutoSize=true,Location=new Point(240,135)};vidas=new Label{AutoSize=true,Location=new Point(400,135)};Controls.Add(jugador);Controls.Add(nivel);Controls.Add(puntaje);Controls.Add(vidas);pregunta=new Label{TextAlign=ContentAlignment.MiddleCenter,Font=new Font("Segoe UI",24,FontStyle.Bold),Location=new Point(100,185),Size=new Size(450,65)};Controls.Add(pregunta);Controls.Add(new Label{Text="Escriba una respuesta numérica:",AutoSize=true,Location=new Point(190,270)});respuesta=new TextBox{Location=new Point(200,300),Width=250,Font=new Font("Segoe UI",14),TextAlign=HorizontalAlignment.Center};respuesta.KeyPress+=(s,e)=>{if(!char.IsControl(e.KeyChar)&&!char.IsDigit(e.KeyChar)&&e.KeyChar!='-')e.Handled=true;};Controls.Add(respuesta);responder=new Button{Text="RESPONDER",Location=new Point(220,350),Size=new Size(210,42)};responder.Click+=Responder_Click;Controls.Add(responder);finalizar=new Button{Text="Finalizar y ver resultados",Location=new Point(200,410),Size=new Size(250,32)};finalizar.Click+=(s,e)=>Terminar();Controls.Add(finalizar);AcceptButton=responder;}
  void Actualizar(){var j=juegos[turno];jugador.Text=(dos?"Turno de: ":"Jugador: ")+jugadores[turno];nivel.Text="Nivel: "+j.Nivel;puntaje.Text="Puntaje: "+j.Puntaje;vidas.Text="Vidas: "+j.Vidas;pregunta.Text=j.A+" "+j.Operacion+" "+j.B+" = ?";respuesta.Clear();respuesta.Focus();}
  void Responder_Click(object s,EventArgs e){int x;if(!int.TryParse(respuesta.Text.Trim(),out x)){MessageBox.Show("Ingrese un número válido.");return;}var j=juegos[turno];bool ok=j.Comprobar(x);MessageBox.Show(ok?"¡Respuesta correcta! +10 puntos.":"Respuesta incorrecta. Se pierde una vida.",ok?"¡Bien!":"Incorrecto");if(j.Vidas<=0){MessageBox.Show(jugadores[turno]+" terminó sus vidas.");Terminar();return;}if(dos)turno=1-turno;Actualizar();}
  void Terminar(){cantidad=0;for(int i=0;i<(dos?2:1);i++){nombres[cantidad]=jugadores[i];puntajes[cantidad]=juegos[i].Puntaje;cantidad++;}for(int i=0;i<cantidad-1;i++)for(int k=i+1;k<cantidad;k++)if(puntajes[k]>puntajes[i]){int p=puntajes[i];puntajes[i]=puntajes[k];puntajes[k]=p;string n=nombres[i];nombres[i]=nombres[k];nombres[k]=n;}Hide();using(var r=new ResultadosForm(nombres,puntajes,cantidad))r.ShowDialog();Close();}
 }
}
